"use client";

import React, { useEffect, useRef, useState, useCallback } from "react";
import { Gauge, AlertTriangle, Navigation } from "lucide-react";

export interface SpeedometerProps {
  /**
   * Speed limit in km/h. If live speed exceeds this, a TTS warning fires.
   * Defaults to 40 km/h.
   */
  speedLimit?: number;
  /**
   * Optional callback to surface the live speed reading to the parent.
   */
  onSpeedUpdate?: (speedKmh: number) => void;
}

type GPSStatus = "acquiring" | "active" | "denied" | "unavailable" | "mock";

// Minimum ms between successive TTS speed-limit warnings (60 s)
const WARNING_COOLDOWN_MS = 60_000;

export default function Speedometer({
  speedLimit = 40,
  onSpeedUpdate,
}: SpeedometerProps) {
  const [speedKmh, setSpeedKmh] = useState<number>(0);
  const [maxSpeedSeen, setMaxSpeedSeen] = useState<number>(0);
  const [gpsStatus, setGpsStatus] = useState<GPSStatus>("acquiring");
  const [isOverLimit, setIsOverLimit] = useState<boolean>(false);
  const [isSpeaking, setIsSpeaking] = useState<boolean>(false);

  const watchIdRef = useRef<number | null>(null);
  const lastWarnedAtRef = useRef<number>(0);
  const isMockedRef = useRef<boolean>(false);

  // ----------------------------------------------------------------
  // TTS Speed Warning (fires at most once per 60 seconds)
  // ----------------------------------------------------------------
  const speakSpeedWarning = useCallback(() => {
    if (typeof window === "undefined") return;
    if (!("speechSynthesis" in window)) return;

    const now = Date.now();
    if (now - lastWarnedAtRef.current < WARNING_COOLDOWN_MS) return;

    lastWarnedAtRef.current = now;

    // Cancel any in-progress speech first
    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(
      "Speed limit exceeded, please slow down."
    );
    utterance.lang = "en-IN";
    utterance.rate = 0.9;
    utterance.pitch = 1.1;
    utterance.volume = 1.0;

    utterance.onstart = () => setIsSpeaking(true);
    utterance.onend = () => setIsSpeaking(false);
    utterance.onerror = () => setIsSpeaking(false);

    window.speechSynthesis.speak(utterance);
    console.log("[Speedometer] TTS warning: speed limit exceeded.");
  }, []);

  // ----------------------------------------------------------------
  // Update state whenever a new GPS speed arrives
  // ----------------------------------------------------------------
  const applySpeed = useCallback(
    (mps: number | null) => {
      // GPS returns null speed when stationary or unavailable
      const kmh = mps != null && mps >= 0 ? Math.round(mps * 3.6) : 0;
      setSpeedKmh(kmh);
      setMaxSpeedSeen((prev) => Math.max(prev, kmh));

      const over = kmh > speedLimit;
      setIsOverLimit(over);

      if (over) {
        speakSpeedWarning();
      }

      if (onSpeedUpdate) {
        onSpeedUpdate(kmh);
      }
    },
    [speedLimit, speakSpeedWarning, onSpeedUpdate]
  );

  // ----------------------------------------------------------------
  // Start navigator.geolocation.watchPosition
  // ----------------------------------------------------------------
  useEffect(() => {
    if (typeof window === "undefined") return;

    if (!("geolocation" in navigator)) {
      setGpsStatus("unavailable");
      startMockGPS();
      return;
    }

    const watchId = navigator.geolocation.watchPosition(
      (position) => {
        setGpsStatus("active");
        applySpeed(position.coords.speed);
      },
      (error) => {
        console.warn("[Speedometer] Geolocation error:", error.code, error.message);
        if (error.code === error.PERMISSION_DENIED) {
          setGpsStatus("denied");
        } else {
          setGpsStatus("unavailable");
        }
        // Fall back to mock telemetry so the HUD stays useful during dev
        if (!isMockedRef.current) {
          startMockGPS();
        }
      },
      {
        enableHighAccuracy: true,
        timeout: 10_000,
        maximumAge: 1_000,
      }
    );

    watchIdRef.current = watchId;

    return () => {
      if (watchIdRef.current !== null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
      if (typeof window !== "undefined" && "speechSynthesis" in window) {
        window.speechSynthesis.cancel();
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Update speed checks when speedLimit prop changes (e.g., dynamic zones)
  useEffect(() => {
    setIsOverLimit(speedKmh > speedLimit);
  }, [speedLimit, speedKmh]);

  // ----------------------------------------------------------------
  // Mock GPS telemetry for dev / desktop environments
  // ----------------------------------------------------------------
  function startMockGPS() {
    isMockedRef.current = true;
    setGpsStatus("mock");
    let mockMps = 10; // start at ~36 km/h

    const interval = setInterval(() => {
      const delta = (Math.random() - 0.4) * 1.5; // slight upward bias
      mockMps = Math.max(0, Math.min(16, mockMps + delta)); // 0–57.6 km/h
      applySpeed(mockMps);
    }, 1800);

    // Store cleanup in watchIdRef using negative sentinel
    watchIdRef.current = -1;
    return interval;
  }

  // ----------------------------------------------------------------
  // Colour logic: green → yellow → red based on speed vs limit
  // ----------------------------------------------------------------
  const getSpeedColour = () => {
    const pct = speedKmh / speedLimit;
    if (pct < 0.75) return "#00ff88"; // safe — neon green
    if (pct < 1.0) return "#ffee00"; // approaching — neon yellow
    return "#ff2a55"; // exceeded — alert crimson
  };

  const speedColour = getSpeedColour();

  // Arc calculation for the circular gauge (200° sweep)
  const radius = 52;
  const circumference = 2 * Math.PI * radius;
  const maxDisplaySpeed = Math.max(speedLimit * 1.5, 80); // scale ceiling
  const arcFraction = Math.min(speedKmh / maxDisplaySpeed, 1);
  const dashOffset = circumference * (1 - arcFraction * (200 / 360));

  return (
    <div
      className={`relative w-full rounded-2xl border-2 overflow-hidden transition-all duration-300 ${
        isOverLimit
          ? "border-[#ff2a55] shadow-[0_0_28px_rgba(255,42,85,0.6)]"
          : "border-neutral-800"
      } bg-black`}
    >
      {/* Background glow when over limit */}
      {isOverLimit && (
        <div className="absolute inset-0 bg-[#ff2a55]/5 pointer-events-none animate-pulse" />
      )}

      <div className="p-4">
        {/* Top status bar */}
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-1.5 text-xs font-mono uppercase text-neutral-400">
            <Navigation className="w-3.5 h-3.5" />
            <span>Live Speed</span>
          </div>

          <div
            className={`flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-mono font-bold border ${
              gpsStatus === "active"
                ? "border-[#00ff88] text-[#00ff88] bg-[#00ff88]/10"
                : gpsStatus === "denied"
                ? "border-rose-600 text-rose-400 bg-rose-950/60"
                : gpsStatus === "mock"
                ? "border-amber-600 text-amber-400 bg-amber-950/60"
                : "border-neutral-600 text-neutral-400"
            }`}
          >
            <span
              className={`w-1.5 h-1.5 rounded-full ${
                gpsStatus === "active"
                  ? "bg-[#00ff88] animate-ping"
                  : gpsStatus === "mock"
                  ? "bg-amber-400"
                  : "bg-neutral-500"
              }`}
            />
            {gpsStatus === "active" && "GPS LIVE"}
            {gpsStatus === "acquiring" && "ACQUIRING..."}
            {gpsStatus === "denied" && "GPS DENIED"}
            {gpsStatus === "unavailable" && "GPS N/A"}
            {gpsStatus === "mock" && "MOCK GPS"}
          </div>
        </div>

        {/* Central Circular Gauge + Big Speed Number */}
        <div className="flex items-center justify-center gap-6">
          {/* SVG arc gauge */}
          <div className="relative flex items-center justify-center w-36 h-36">
            <svg
              viewBox="0 0 120 120"
              className="w-full h-full -rotate-[100deg]"
              aria-hidden="true"
            >
              {/* Background track */}
              <circle
                cx="60"
                cy="60"
                r={radius}
                fill="none"
                stroke="#1a1a1a"
                strokeWidth="10"
                strokeDasharray={`${circumference * 0.556} ${circumference * 0.444}`}
                strokeLinecap="round"
              />
              {/* Live speed arc */}
              <circle
                cx="60"
                cy="60"
                r={radius}
                fill="none"
                stroke={speedColour}
                strokeWidth="10"
                strokeLinecap="round"
                strokeDasharray={`${circumference * 0.556 * arcFraction} ${circumference * (1 - 0.556 * arcFraction)}`}
                style={{ transition: "stroke-dasharray 0.4s ease, stroke 0.3s ease" }}
              />
            </svg>

            {/* Centred speed reading */}
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span
                className="text-4xl font-black font-mono leading-none tracking-tighter transition-colors duration-300"
                style={{ color: speedColour }}
              >
                {speedKmh}
              </span>
              <span className="text-[10px] font-mono text-neutral-500 mt-0.5 uppercase">
                km/h
              </span>
            </div>
          </div>

          {/* Right stats column */}
          <div className="flex flex-col gap-3">
            {/* Speed limit badge */}
            <div className="flex flex-col">
              <span className="text-[9px] font-mono text-neutral-500 uppercase tracking-widest">
                Limit
              </span>
              <div className="flex items-center gap-1">
                <Gauge className="w-3.5 h-3.5 text-neutral-400" />
                <span className="text-lg font-black font-mono text-white">
                  {speedLimit}
                </span>
                <span className="text-[10px] text-neutral-500 font-mono">km/h</span>
              </div>
            </div>

            {/* Max speed recorded */}
            <div className="flex flex-col">
              <span className="text-[9px] font-mono text-neutral-500 uppercase tracking-widest">
                Max
              </span>
              <span className="text-lg font-black font-mono text-[#00f0ff]">
                {maxSpeedSeen}
                <span className="text-[10px] text-neutral-500 font-mono ml-0.5">
                  km/h
                </span>
              </span>
            </div>

            {/* TTS speaking indicator */}
            {isSpeaking && (
              <div className="flex items-center gap-1 text-[10px] font-mono text-amber-400">
                <span className="animate-ping w-1.5 h-1.5 rounded-full bg-amber-400" />
                Speaking...
              </div>
            )}
          </div>
        </div>

        {/* Over-limit alert banner */}
        {isOverLimit && (
          <div className="mt-3 flex items-center justify-center gap-2 py-2 px-4 rounded-xl bg-[#ff2a55]/15 border border-[#ff2a55]/60 text-[#ff2a55] text-xs font-black uppercase tracking-widest animate-pulse">
            <AlertTriangle className="w-4 h-4" />
            <span>Speed Limit Exceeded — Slow Down!</span>
          </div>
        )}
      </div>
    </div>
  );
}

